window.MQ_FRENCH_2026_2027 = [{"level":"6","id":"fr6a","name":"Lire avec fluidité et expressivité","icon":"📖","domain":"Lecture","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Lire avec fluidité et expressivité ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["En 6e, la lecture silencieuse et à voix haute reste un entraînement régulier.","Le phrasé suit les groupes de sens et la ponctuation.","L’objectif de fluidité indiqué par le programme est d’environ 130 mots par minute en moyenne, sans sacrifier la compréhension."],"method":["Repère la ponctuation et les groupes de sens.","Prépare les mots difficiles et les liaisons.","Lis une première fois pour comprendre, puis une seconde pour interpréter."],"example":{"q":"Comment lire « Soudain, derrière la porte, un bruit éclata. » ?","s":["Marque une courte pause après « Soudain ».","Fais monter légèrement la tension avant « un bruit ».","Accentue « éclata » sans crier.","La lecture expressive sert le sens, elle ne consiste pas à jouer au hasard."]},"trap":"Chercher la vitesse maximale et oublier le sens ou la ponctuation.","retain":["Fluidité = exactitude + rythme + compréhension.","La ponctuation aide à découper le sens.","Une lecture expressive se prépare."],"quiz":[{"t":"choice","q":"Quel objectif est visé en 6e pour la fluidité de lecture ?","a":"Environ 130 mots par minute en moyenne","bad":["50 mots par minute","300 mots par minute","Aucune lecture à voix haute"],"hint":"Le programme donne un repère chiffré.","expl":"Le programme de cycle 3 indique environ 130 mots par minute en moyenne en 6e."}]},{"level":"6","id":"fr6b","name":"Comprendre l’explicite et l’implicite","icon":"🕵️","domain":"Lecture","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Comprendre l’explicite et l’implicite ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une information explicite est écrite directement.","Une information implicite se déduit grâce à plusieurs indices du texte et à ses connaissances.","Une interprétation doit être justifiée par un mot, une phrase ou un détail précis."],"method":["Lis d’abord la question.","Surligne les indices utiles.","Formule la déduction puis cite l’indice qui la prouve."],"example":{"q":"« Lina referma son parapluie en entrant et secoua ses chaussures mouillées. » Quel temps fait-il probablement ?","s":["Le texte ne dit pas « il pleut » : c’est implicite.","Le parapluie et les chaussures mouillées sont deux indices.","On peut répondre : « Il pleut probablement, car Lina a un parapluie et ses chaussures sont mouillées. »"]},"trap":"Répondre avec son imagination sans s’appuyer sur le texte.","retain":["Explicite = écrit.","Implicite = déduit.","Toujours justifier avec un indice."],"quiz":[{"t":"choice","q":"Une information implicite est…","a":"une information que l’on déduit grâce aux indices","bad":["une information toujours écrite en gras","une faute d’orthographe","le titre uniquement"],"hint":"Elle n’est pas dite directement.","expl":"L’implicite se construit à partir d’indices."}]},{"level":"6","id":"fr6c","name":"Lire documents, images et sources","icon":"📰","domain":"Lecture","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Lire documents, images et sources ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Un document possède une nature, une source, un auteur éventuel, une date et une intention.","Un document composite peut associer texte, image, tableau, graphique ou légende.","Comparer deux documents permet de repérer convergences, différences et informations complémentaires."],"method":["Identifie la nature et la source.","Observe le titre, la légende et les unités.","Relie les informations au lieu de lire chaque élément séparément."],"example":{"q":"Une affiche comporte un slogan, une photographie et la date « 1918 ». Par quoi commencer ?","s":["Identifier qu’il s’agit d’une affiche.","Lire la source, la date et le contexte si disponibles.","Observer le lien entre le slogan et l’image.","Seulement ensuite interpréter le message."]},"trap":"Interpréter une image sans regarder sa légende ni sa source.","retain":["Nature + source + date avant interprétation.","Un document composite se lit dans son ensemble.","Comparer aide à comprendre."],"quiz":[]},{"level":"6","id":"fr6d","name":"Récits des origines : créer et recréer le monde","icon":"🌍","domain":"Culture littéraire et artistique","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Récits des origines : créer et recréer le monde ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les récits des origines expliquent symboliquement la naissance du monde, des humains ou d’un peuple.","Ils utilisent souvent des forces surnaturelles, des dieux, des héros ou des transformations.","Comparer plusieurs traditions permet d’identifier ressemblances, différences et valeurs culturelles."],"method":["Repère ce qui est expliqué par le récit.","Identifie les personnages ou forces créatrices.","Demande-toi quelles valeurs et quelle vision du monde sont transmises."],"example":{"q":"Dans un récit, une divinité sépare la lumière et l’obscurité puis organise les éléments. Que cherche le récit à expliquer ?","s":["Il met en scène l’organisation du monde.","Les actions ont une portée symbolique.","On ne lit pas ce type de récit comme un compte rendu scientifique."]},"trap":"Confondre un récit fondateur avec une explication scientifique moderne.","retain":["Un récit des origines donne du sens au monde.","Il appartient à une culture et à une tradition.","Comparer les récits développe l’interprétation."],"quiz":[]},{"level":"6","id":"fr6e","name":"Poésie : chanter et enchanter le monde","icon":"🎵","domain":"Culture littéraire et artistique","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Poésie : chanter et enchanter le monde ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["La poésie travaille les sons, le rythme, les images et la disposition des mots.","Comparaison, métaphore et personnification transforment notre perception du réel.","Lire un poème à voix haute aide à entendre ses effets."],"method":["Repère les mots qui reviennent et les sons dominants.","Cherche les images poétiques.","Explique l’émotion ou la vision du monde produite."],"example":{"q":"« La lune est une lampe suspendue au ciel. » Quel procédé reconnais-tu ?","s":["La lune est assimilée à une lampe sans outil de comparaison.","C’est une métaphore.","L’image rend la lune plus proche et concrète."]},"trap":"Se contenter de repérer une figure sans expliquer son effet.","retain":["Poésie = sons + rythme + images.","Nommer le procédé puis expliquer l’effet.","La lecture à voix haute fait partie de l’analyse."],"quiz":[]},{"level":"6","id":"fr6f","name":"Théâtre : ruses, jeu et mise en scène","icon":"🎭","domain":"Culture littéraire et artistique","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Théâtre : ruses, jeu et mise en scène ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le théâtre est un texte écrit pour être joué.","Répliques, didascalies, scènes et actes organisent l’action.","La ruse produit souvent quiproquos, retournements et comique."],"method":["Repère qui parle et à qui.","Lis les didascalies : elles guident gestes, ton et déplacements.","Cherche ce que le public sait que certains personnages ignorent."],"example":{"q":"Un personnage cache une lettre pendant qu’un autre arrive. Pourquoi une didascalie est-elle importante ?","s":["Elle indique une action qui n’est pas prononcée.","Elle peut créer du suspense ou du comique.","Le jeu de scène complète le dialogue."]},"trap":"Lire les didascalies comme si un personnage les disait à voix haute.","retain":["Le théâtre se lit et se joue.","Didascalies = indications scéniques.","La ruse peut faire avancer l’action."],"quiz":[]},{"level":"6","id":"fr6g","name":"Partir à l’aventure : récit et héros","icon":"🧭","domain":"Culture littéraire et artistique","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Partir à l’aventure : récit et héros ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le récit d’aventure repose sur un départ, des obstacles, des choix et des transformations.","Le héros ou l’héroïne agit dans un univers souvent nouveau ou dangereux.","Le rythme du récit accélère dans l’action et ralentit dans la description ou la réflexion."],"method":["Repère la situation de départ.","Identifie l’épreuve et le choix du personnage.","Observe ce qui a changé à la fin."],"example":{"q":"Pourquoi une tempête peut-elle être plus qu’un simple décor dans un récit d’aventure ?","s":["Elle crée un obstacle.","Elle oblige le personnage à agir et révèle son caractère.","Elle peut modifier la suite du voyage."]},"trap":"Résumer seulement les événements sans expliquer ce qu’ils changent pour le personnage.","retain":["Aventure = déplacement + épreuves + transformation.","Le décor peut devenir un obstacle.","Le rythme contribue au suspense."],"quiz":[]},{"level":"6","id":"fr6h","name":"Rencontrer des monstres : peur et altérité","icon":"🐉","domain":"Culture littéraire et artistique","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Rencontrer des monstres : peur et altérité ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le monstre peut être effrayant, merveilleux, comique ou tragique.","Il interroge la frontière entre humain et non-humain, normal et étrange.","La rencontre du monstre révèle souvent les peurs et les qualités du héros."],"method":["Décris le monstre précisément.","Repère la réaction des personnages.","Demande-toi ce que cette créature représente symboliquement."],"example":{"q":"Un monstre protège son territoire et ne combat que lorsqu’on l’attaque. Est-il forcément « méchant » ?","s":["Non : le texte invite à nuancer.","Il faut distinguer apparence, actions et point de vue du narrateur.","L’altérité peut faire peur sans être mauvaise."]},"trap":"Décider qu’un personnage est mauvais uniquement parce qu’il est différent.","retain":["Le monstre questionne l’autre et soi-même.","Apparence et morale ne se confondent pas.","Le point de vue influence le jugement."],"quiz":[]},{"level":"6","id":"fr6i","name":"Types, formes de phrases et ponctuation","icon":"❗","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Types, formes de phrases et ponctuation ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les types fondamentaux sont déclaratif, interrogatif et impératif/injonctif.","Les formes négative et exclamative modifient la construction ou l’effet de la phrase.","La ponctuation structure la syntaxe et le sens."],"method":["Cherche l’intention : informer, questionner ou donner un ordre.","Observe le verbe et la ponctuation.","Transforme la phrase pour vérifier."],"example":{"q":"Transforme « Tu fermes la porte. » en phrase interrogative puis impérative.","s":["Interrogative : « Est-ce que tu fermes la porte ? » ou « Fermes-tu la porte ? »","Impérative : « Ferme la porte. »","La ponctuation change avec le type."]},"trap":"Confondre type de phrase et forme de phrase.","retain":["Type = intention syntaxique.","Forme = négative/exclamative notamment.","La ponctuation guide la lecture."],"quiz":[]},{"level":"6","id":"fr6j","name":"Nature et fonction : classes de mots","icon":"🧱","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Nature et fonction : classes de mots ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["La nature d’un mot indique ce qu’il est : nom, déterminant, adjectif, pronom, verbe, adverbe, préposition, conjonction.","La fonction indique son rôle dans la phrase : sujet, COD, complément du nom, etc.","Un même groupe peut changer de fonction sans changer de nature."],"method":["Identifie d’abord le mot ou groupe.","Cherche sa classe grammaticale.","Ensuite seulement, cherche son rôle dans la phrase."],"example":{"q":"Dans « Le chat observe la souris », quelle est la nature et la fonction de « le chat » ?","s":["Nature : groupe nominal.","Fonction : sujet du verbe « observe ».","On vérifie avec « C’est le chat qui observe… »."]},"trap":"Répondre « sujet » quand on demande la nature.","retain":["Nature = identité grammaticale.","Fonction = rôle.","Toujours préciser les deux séparément."],"quiz":[]},{"level":"6","id":"fr6k","name":"Sujet, COD, COI, attribut et compléments","icon":"🎯","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Sujet, COD, COI, attribut et compléments ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le sujet commande l’accord du verbe.","COD et COI complètent le verbe ; le COI est généralement introduit par une préposition.","L’attribut du sujet caractérise le sujet avec un verbe attributif ; les compléments circonstanciels peuvent souvent être déplacés ou supprimés."],"method":["Repère le verbe conjugué.","Cherche le sujet.","Teste suppression, déplacement et pronominalisation pour les compléments."],"example":{"q":"Analyse « Ce matin, Léa semble heureuse et parle à son frère. »","s":["« Ce matin » : complément circonstanciel.","« Léa » : sujet.","« heureuse » : attribut du sujet après « semble ».","« à son frère » : COI de « parle »."]},"trap":"Croire que tout groupe après un verbe est un COD.","retain":["Les fonctions se vérifient par manipulations.","COI souvent avec préposition.","Attribut = caractéristique du sujet."],"quiz":[]},{"level":"6","id":"fr6l","name":"Le groupe nominal et ses expansions","icon":"🌳","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Le groupe nominal et ses expansions ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le nom noyau commande le groupe nominal.","L’adjectif épithète et le complément du nom enrichissent le nom.","Un groupe nominal prépositionnel peut être complément du nom."],"method":["Trouve le nom noyau.","Repère le déterminant.","Ajoute ou retire les expansions pour voir ce qui est essentiel."],"example":{"q":"Dans « la grande maison de pierre », quel est le noyau et quelles sont les expansions ?","s":["Noyau : « maison ».","« grande » : adjectif épithète.","« de pierre » : complément du nom."]},"trap":"Prendre le dernier mot du groupe pour le noyau.","retain":["Noyau = nom principal.","Adjectif épithète et complément du nom sont des expansions.","Le déterminant introduit souvent le groupe nominal."],"quiz":[]},{"level":"6","id":"fr6m","name":"Pronoms personnels et antécédents","icon":"🔁","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Pronoms personnels et antécédents ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Un pronom remplace ou reprend un nom ou un groupe nominal.","L’antécédent est le mot ou groupe repris par le pronom.","Les pronoms personnels peuvent être sujets ou compléments."],"method":["Repère le pronom.","Cherche ce qu’il remplace.","Vérifie que genre, nombre et sens restent cohérents."],"example":{"q":"« Les filles voient Tom. Elles le saluent. » Que reprennent « elles » et « le » ?","s":["« elles » reprend « les filles ».","« le » reprend « Tom ».","Les pronoms évitent les répétitions."]},"trap":"Choisir un antécédent seulement parce qu’il est le mot le plus proche.","retain":["Pronom = mot de reprise.","Antécédent = élément repris.","Sens et accord permettent de vérifier."],"quiz":[]},{"level":"6","id":"fr6n","name":"Phrase simple, phrase complexe et propositions","icon":"🔗","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Phrase simple, phrase complexe et propositions ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une phrase simple contient une seule proposition organisée autour d’un verbe conjugué.","Une phrase complexe contient plusieurs propositions.","Repérer les verbes conjugués aide à compter les propositions."],"method":["Encadre les verbes conjugués.","Compte les noyaux verbaux.","Délimite les propositions et observe leur lien."],"example":{"q":"« Le soleil se couche et les oiseaux rentrent. » simple ou complexe ?","s":["Deux verbes conjugués : « se couche » et « rentrent ».","Il y a deux propositions.","La phrase est complexe."]},"trap":"Compter les infinitifs comme des propositions indépendantes.","retain":["Verbes conjugués = premier repère.","Phrase complexe = plusieurs propositions.","Une proposition s’organise autour d’un noyau verbal."],"quiz":[]},{"level":"6","id":"fr6o","name":"Juxtaposition, coordination et subordination","icon":"🧷","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Juxtaposition, coordination et subordination ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les propositions peuvent être juxtaposées par un signe de ponctuation.","Elles peuvent être coordonnées par « mais, ou, et, donc, or, ni, car » notamment.","La subordination crée une dépendance syntaxique avec un mot subordonnant."],"method":["Repère la frontière entre propositions.","Cherche le signe ou mot de liaison.","Nomme le lien et explique le rapport de sens."],"example":{"q":"« Il pleut, je prends mon parapluie. » Quel lien ?","s":["Deux propositions séparées par une virgule.","Elles sont juxtaposées.","Le sens suggère ici une relation de cause à conséquence."]},"trap":"Croire qu’une virgule signifie toujours coordination.","retain":["Juxtaposition = ponctuation.","Coordination = mot coordonnant.","Subordination = proposition dépendante."],"quiz":[]},{"level":"6","id":"fr6p","name":"Accords dans le groupe nominal","icon":"✅","domain":"Orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Accords dans le groupe nominal ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le nom noyau donne genre et nombre aux déterminants et adjectifs qui s’accordent avec lui.","Les marques de pluriel et de féminin doivent être cohérentes dans toute la chaîne.","Certains pluriels ou féminins sont irréguliers et doivent être mémorisés."],"method":["Repère le nom noyau.","Détermine genre et nombre.","Contrôle chaque déterminant et adjectif lié au nom."],"example":{"q":"Mets au pluriel : « ce petit cheval noir ».","s":["Nom : cheval → chevaux.","Déterminant : ce → ces.","Adjectifs : petit → petits ; noir → noirs.","Réponse : « ces petits chevaux noirs »."]},"trap":"Accorder uniquement le nom et oublier les autres mots du groupe.","retain":["Accord en chaîne dans le GN.","Le nom noyau est le donneur d’accord.","Vérifie déterminant + nom + adjectif."],"quiz":[]},{"level":"6","id":"fr6q","name":"Accord sujet-verbe","icon":"🤝","domain":"Orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Accord sujet-verbe ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le verbe s’accorde avec son sujet en personne et en nombre.","Le sujet peut être éloigné du verbe ou inversé.","Dans un groupe sujet, on repère le noyau qui commande l’accord."],"method":["Repère le verbe.","Pose la question « qui est-ce qui… ? ».","Remplace le sujet par un pronom pour vérifier la terminaison."],"example":{"q":"Choisis : « La troupe de musiciens joue / jouent. »","s":["Le noyau du sujet est « troupe », singulier.","« de musiciens » complète le nom mais ne commande pas le verbe.","On écrit « La troupe de musiciens joue. »"]},"trap":"Accorder le verbe avec le nom le plus proche.","retain":["Accord avec le noyau du sujet.","Distance ne change pas la règle.","Remplacer par il/elle/ils/elles aide."],"quiz":[]},{"level":"6","id":"fr6r","name":"Présent, imparfait et futur","icon":"⏱️","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Présent, imparfait et futur ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les terminaisons portent des marques de personne et parfois de temps.","L’imparfait contient généralement la marque -ai-/-i- ; le futur la marque -r-.","Il faut connaître les radicaux irréguliers des verbes fréquents."],"method":["Identifie l’infinitif et le sujet.","Choisis le temps selon le sens.","Construis radical + marque du temps + marque de personne."],"example":{"q":"Conjugue « venir » avec « nous » au futur.","s":["Radical du futur : viendr-.","Marque de personne « nous » : -ons.","Réponse : « nous viendrons »."]},"trap":"Ajouter une terminaison régulière à un radical irrégulier faux.","retain":["Temps + personne se lisent dans la forme verbale.","Les verbes fréquents irréguliers se mémorisent.","Le sens détermine le temps."],"quiz":[]},{"level":"6","id":"fr6s","name":"Passé composé et plus-que-parfait","icon":"⏮️","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Passé composé et plus-que-parfait ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Un temps composé contient un auxiliaire et un participe passé.","Passé composé : auxiliaire au présent + participe passé.","Plus-que-parfait : auxiliaire à l’imparfait + participe passé."],"method":["Repère l’auxiliaire être ou avoir.","Conjugue l’auxiliaire au bon temps.","Ajoute le participe passé et vérifie son accord."],"example":{"q":"Transforme « Elle termine son travail » au plus-que-parfait.","s":["Auxiliaire avoir à l’imparfait : « avait ».","Participe passé de terminer : « terminé ».","« Elle avait terminé son travail. »"]},"trap":"Conjuguer le participe passé comme s’il était un verbe simple.","retain":["Temps composé = auxiliaire + participe passé.","Le temps de l’auxiliaire distingue passé composé et plus-que-parfait.","L’accord du participe passé doit être vérifié."],"quiz":[]},{"level":"6","id":"fr6t","name":"Passé simple et temps du récit","icon":"📚","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Passé simple et temps du récit ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le passé simple est fréquent dans les récits écrits pour les actions de premier plan.","L’imparfait sert souvent au décor, aux habitudes, aux descriptions ou aux actions en cours.","Les valeurs des temps dépendent du contexte et du point de vue du récit."],"method":["Repère ce qui constitue le décor.","Repère les actions soudaines ou successives.","Observe l’alternance imparfait/passé simple."],"example":{"q":"« La nuit était calme quand une porte claqua. » Explique les temps.","s":["« était » à l’imparfait installe le décor.","« claqua » au passé simple marque un événement ponctuel.","L’alternance crée une rupture dans le récit."]},"trap":"Croire qu’un temps verbal correspond toujours à une seule valeur.","retain":["Imparfait souvent arrière-plan.","Passé simple souvent premier plan narratif.","La valeur se comprend dans le contexte."],"quiz":[]},{"level":"6","id":"fr6u","name":"Impératif et conditionnel présent","icon":"🎛️","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Impératif et conditionnel présent ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["L’impératif sert notamment à donner une consigne, un conseil ou un ordre.","Le conditionnel présent peut exprimer l’hypothèse, le souhait ou la politesse.","Les formes fréquentes des verbes irréguliers doivent être maîtrisées."],"method":["Identifie l’intention de la phrase.","Choisis le mode adapté.","Vérifie les personnes possibles et les terminaisons."],"example":{"q":"Transforme « Tu prends ton cahier » en consigne puis en demande polie.","s":["Impératif : « Prends ton cahier. »","Demande au conditionnel : « Pourrais-tu prendre ton cahier ? »","Le mode change l’effet produit."]},"trap":"Écrire le sujet devant un impératif affirmatif ordinaire.","retain":["Impératif = consigne/conseil.","Conditionnel = hypothèse/souhait/politesse selon le contexte.","Le sens guide le choix du mode."],"quiz":[]},{"level":"6","id":"fr6v","name":"Former les mots et enrichir son vocabulaire","icon":"🧬","domain":"Vocabulaire et orthographe lexicale","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Former les mots et enrichir son vocabulaire ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Préfixe, radical et suffixe aident à comprendre et construire des mots.","Synonymes, antonymes, homonymes et polysémie organisent les relations de sens.","L’étymologie éclaire l’histoire et parfois l’orthographe des mots."],"method":["Cherche le radical.","Repère les éléments ajoutés.","Vérifie le sens en contexte puis dans un dictionnaire si nécessaire."],"example":{"q":"Que peux-tu déduire de « impossible » ?","s":["Radical : « possible ».","Préfixe im- exprime ici la négation.","Le mot signifie « qui n’est pas possible »."]},"trap":"Découper un mot au hasard sans vérifier si les morceaux ont un sens.","retain":["Morphologie = outil de compréhension.","Le contexte décide du sens d’un mot polysémique.","Réemployer un mot aide à le mémoriser."],"quiz":[]},{"level":"6","id":"fr6w","name":"Orthographe lexicale et dictée raisonnée","icon":"✍️","domain":"Vocabulaire et orthographe lexicale","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Orthographe lexicale et dictée raisonnée ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["L’orthographe d’un mot se mémorise mieux quand on comprend sa famille et sa formation.","Une dictée raisonnée consiste à justifier les choix plutôt qu’à deviner.","Les mots fréquents et irréguliers doivent devenir automatiques."],"method":["Repère les mots connus et les familles de mots.","Pour chaque hésitation, formule une hypothèse.","Vérifie avec la morphologie, le contexte ou un outil de référence."],"example":{"q":"Pourquoi « terrain » prend-il deux r ?","s":["On peut le relier à « terre ».","La famille de mots aide à mémoriser le radical.","On vérifie ensuite dans un dictionnaire si nécessaire."]},"trap":"Recopier dix fois un mot sans chercher de stratégie de mémorisation.","retain":["Observer la famille du mot.","Justifier avant de vérifier.","Réemployer le mot dans une phrase."],"quiz":[]},{"level":"6","id":"fr6x","name":"Écrire un récit et une description","icon":"📝","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Écrire un récit et une description ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Un récit cohérent enchaîne situation, événements et évolution des personnages.","La description sélectionne des détails et les organise selon un point de vue.","Les connecteurs et les reprises évitent les ruptures et les répétitions."],"method":["Prépare un plan très court au brouillon.","Écris un premier jet sans chercher la perfection.","Relis une fois pour le sens puis une fois pour la langue."],"example":{"q":"Tu dois raconter une entrée dans un château abandonné. Comment organiser le paragraphe ?","s":["Situe d’abord le personnage et le lieu.","Choisis 2 ou 3 détails sensoriels significatifs.","Fais survenir un événement qui relance l’action.","Relis les temps verbaux et les reprises."]},"trap":"Empiler des adjectifs sans sélectionner les détails utiles.","retain":["Brouillon = outil de pensée.","Un détail précis vaut mieux qu’une longue liste.","Relire séparément le sens et l’orthographe."],"quiz":[]},{"level":"6","id":"fr6y","name":"Répondre, justifier et résumer","icon":"🧠","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Répondre, justifier et résumer ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une réponse complète reprend les mots de la question sans la recopier mécaniquement.","Justifier consiste à apporter une preuve : citation courte, indice, exemple ou explication.","Résumer conserve l’essentiel et respecte l’ordre des idées."],"method":["Réponds d’abord clairement.","Ajoute la preuve.","Explique le lien entre la preuve et ta réponse."],"example":{"q":"Question : « Pourquoi le personnage a-t-il peur ? »","s":["Réponse : « Le personnage a peur parce qu’il se croit suivi. »","Preuve : le texte indique qu’il « se retourne sans cesse ».","Explication : ce comportement montre son inquiétude."]},"trap":"Donner seulement une citation sans expliquer ce qu’elle prouve.","retain":["Réponse + preuve + explication.","Une citation doit être courte et utile.","Résumer n’est pas recopier."],"quiz":[]},{"level":"6","id":"fr6z","name":"Prendre la parole, écouter et débattre","icon":"🎙️","domain":"Oral","objectives":["Prendre la parole de façon claire, écouter, interagir et adapter son propos à la situation.","Maîtriser les notions essentielles du chapitre « Prendre la parole, écouter et débattre ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Un oral clair possède une idée directrice, un ordre et un vocabulaire adapté.","Écouter permet de reformuler avant de répondre.","Dans un débat, on s’appuie sur des arguments et on respecte les tours de parole."],"method":["Prépare trois idées-clés, pas un texte entier.","Regarde l’auditoire et parle assez lentement.","Pour répondre, reformule d’abord l’idée de l’autre."],"example":{"q":"Présente un livre en une minute.","s":["Donne titre, auteur/autrice et genre.","Présente brièvement le sujet sans révéler toute la fin.","Explique ce que tu as aimé ou non avec un exemple.","Termine par une recommandation claire."]},"trap":"Lire entièrement ses notes sans regarder l’auditoire.","retain":["Oral = structure + voix + écoute.","Une opinion se justifie.","Le débat n’est pas une dispute."],"quiz":[]},{"level":"5","id":"fr5a","name":"Comprendre, interpréter et apprécier un texte","icon":"🔎","domain":"Lecture","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Comprendre, interpréter et apprécier un texte ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Comprendre ne suffit pas : en 5e, on commence à construire une interprétation personnelle argumentée.","Une interprétation repose sur des éléments précis du texte et peut être discutée.","Le contexte, le genre et le point de vue aident à comprendre les effets produits."],"method":["Résume d’abord le sens littéral.","Repère les procédés et indices significatifs.","Propose une interprétation et justifie-la par le texte."],"example":{"q":"Un narrateur décrit une ville comme « une gueule immense qui avale les passants ». Que suggère cette image ?","s":["La ville est comparée à une créature menaçante.","L’image traduit un sentiment d’oppression.","On justifie avec les mots « gueule » et « avale »."]},"trap":"Donner une opinion sans preuve textuelle.","retain":["Interpréter = proposer du sens + justifier.","Le procédé n’a d’intérêt que si on explique son effet.","Plusieurs interprétations peuvent coexister si elles sont argumentées."],"quiz":[]},{"level":"5","id":"fr5b","name":"Écrire pour s’approprier une lecture","icon":"📓","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Écrire pour s’approprier une lecture ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["L’écrit d’appropriation aide à comprendre une œuvre en changeant de point de vue, en reformulant ou en prolongeant.","Le nouveau programme demande des écrits réguliers, articulés aux lectures.","Un bon écrit respecte l’univers, les personnages et les contraintes de la consigne."],"method":["Repère les contraintes du texte source.","Choisis ce que tu veux faire comprendre du personnage.","Relis pour vérifier cohérence, temps et vocabulaire."],"example":{"q":"Écris quelques lignes du journal intime d’un héros après une épreuve.","s":["Utilise la première personne.","Rappelle l’épreuve sans tout résumer.","Exprime pensées et émotions cohérentes avec le personnage.","Fais sentir ce qu’il a appris."]},"trap":"Changer complètement la personnalité du personnage sans justification.","retain":["S’approprier = comprendre en réécrivant.","Respecter les contraintes du texte source.","Révision du brouillon indispensable."],"quiz":[]},{"level":"5","id":"fr5c","name":"Prendre la parole et interagir","icon":"🗣️","domain":"Oral","objectives":["Prendre la parole de façon claire, écouter, interagir et adapter son propos à la situation.","Maîtriser les notions essentielles du chapitre « Prendre la parole et interagir ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["En 5e, on apprend à parler seul de façon fluide et à entrer dans un dialogue construit.","Une prise de parole scolaire adapte niveau de langue, débit et vocabulaire.","Écouter une objection permet d’ajuster sa réponse."],"method":["Annonce ton idée principale.","Développe avec un exemple.","Écoute puis réponds au point précis soulevé."],"example":{"q":"Défends le choix d’un personnage en 45 secondes.","s":["Annonce clairement ta position.","Donne un argument.","Appuie-toi sur un événement du récit.","Conclue en une phrase."]},"trap":"Parler plus vite pour donner l’impression de tout savoir.","retain":["Oral = clarté, écoute, interaction.","Un exemple renforce un argument.","Le registre s’adapte au contexte."],"quiz":[]},{"level":"5","id":"fr5d","name":"Devenir héroïne ou héros : destins romanesques","icon":"🦸","domain":"Culture littéraire et artistique","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Devenir héroïne ou héros : destins romanesques ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le nouveau programme de 5e interroge les figures héroïques de l’Antiquité à aujourd’hui.","Un héros peut être admirable, ambigu, collectif ou même ordinaire.","Les récits héroïques transmettent et questionnent des valeurs."],"method":["Repère les qualités et les faiblesses du personnage.","Identifie les épreuves.","Demande quelles valeurs le texte propose ou critique."],"example":{"q":"Un personnage refuse de fuir pour protéger les autres malgré sa peur. En quoi est-il héroïque ?","s":["Le courage n’est pas l’absence de peur.","Il agit pour une valeur et pour autrui.","Son choix et ses conséquences construisent l’héroïsme."]},"trap":"Confondre héros principal et héros exemplaire.","retain":["Personnage principal ≠ forcément héroïque.","L’héroïsme se construit par actes et valeurs.","Les modèles héroïques évoluent selon les époques."],"quiz":[]},{"level":"5","id":"fr5e","name":"Voyager en poésie","icon":"🗺️","domain":"Culture littéraire et artistique","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Voyager en poésie ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le voyage poétique peut être géographique, intérieur ou imaginaire.","Les sons, rythmes, images et formes transforment l’espace et les sensations.","Les traditions poétiques peuvent être patrimoniales, contemporaines ou francophones."],"method":["Repère le mouvement du poème.","Observe les sensations et les images.","Explique comment la langue produit le dépaysement."],"example":{"q":"Pourquoi un poète peut-il décrire un lieu réel de façon irréaliste ?","s":["La poésie transforme le regard.","Les images expriment une sensation ou un état intérieur.","Le lieu devient aussi une expérience personnelle."]},"trap":"Réduire le poème à une liste de figures de style.","retain":["Poésie = expérience du langage.","Voyage extérieur et voyage intérieur peuvent se mêler.","Toujours relier forme et effet."],"quiz":[]},{"level":"5","id":"fr5f","name":"Théâtre : la société sens dessus dessous","icon":"🎭","domain":"Culture littéraire et artistique","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Théâtre : la société sens dessus dessous ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le théâtre peut renverser provisoirement les hiérarchies et les rôles sociaux.","Le comique révèle souvent des tensions entre dominants et dominés.","Jeu scénique, rythme, gestes et double énonciation participent au sens."],"method":["Repère qui détient le pouvoir au début.","Observe les renversements.","Explique ce que le rire permet de critiquer."],"example":{"q":"Un valet donne des ordres à son maître le temps d’une scène. Quel effet possible ?","s":["Le renversement crée du comique.","Il permet aussi de montrer l’arbitraire d’une hiérarchie.","La scène peut faire réfléchir en faisant rire."]},"trap":"Croire que le comique empêche toute critique sérieuse.","retain":["Le théâtre met la société à l’épreuve.","Le rire peut être critique.","La représentation compte autant que le texte."],"quiz":[]},{"level":"5","id":"fr5g","name":"Histoires pour plaire et instruire","icon":"🦊","domain":"Culture littéraire et artistique","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Histoires pour plaire et instruire ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Contes, fables et autres récits brefs associent plaisir de raconter et réflexion morale.","Les personnages peuvent incarner des traits humains ou sociaux.","La morale peut être explicite, implicite ou discutée."],"method":["Résume la situation et le conflit.","Identifie ce que les personnages représentent.","Formule la leçon possible et vérifie si le texte la nuance."],"example":{"q":"Dans une fable, un personnage gagne en trompant un autre. La morale est-elle forcément « il faut tromper » ?","s":["Non : le récit peut au contraire dénoncer la naïveté, la flatterie ou la ruse.","Il faut analyser le point de vue et la chute.","La morale ne se réduit pas au résultat de l’action."]},"trap":"Prendre l’action du vainqueur pour la morale du texte.","retain":["Récit plaisant et réflexion peuvent aller ensemble.","Une morale s’interprète.","Le personnage peut symboliser un comportement."],"quiz":[]},{"level":"5","id":"fr5h","name":"Enrichir et organiser son vocabulaire","icon":"🧠","domain":"Vocabulaire et orthographe lexicale","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Enrichir et organiser son vocabulaire ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le sens d’un mot se déduit d’abord du contexte, puis se vérifie.","Les mots s’organisent en familles et réseaux de sens.","Un vocabulaire précis améliore lecture, écriture et oral."],"method":["Propose une hypothèse de sens.","Observe famille, préfixe, suffixe et contexte.","Vérifie au dictionnaire puis réemploie le mot."],"example":{"q":"Tu rencontres « intrépide » dans un portrait héroïque. Comment chercher son sens ?","s":["Observe le contexte : le personnage affronte le danger.","Formule « courageux, qui n’a pas peur ».","Vérifie puis réemploie le mot dans une phrase."]},"trap":"Ouvrir immédiatement le dictionnaire sans essayer de déduire.","retain":["Déduire puis vérifier.","Classer les mots aide à les mémoriser.","Réemployer fixe durablement le vocabulaire."],"quiz":[]},{"level":"5","id":"fr5i","name":"Préfixes, suffixes, étymologie et registres","icon":"🧬","domain":"Vocabulaire et orthographe lexicale","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Préfixes, suffixes, étymologie et registres ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Préfixes et suffixes modifient sens ou classe d’un mot.","L’étymologie permet de comprendre des familles et certaines graphies.","Les registres familier, courant et soutenu dépendent de la situation de communication."],"method":["Décompose le mot.","Relie-le à sa famille et à son origine si connue.","Choisis ensuite le registre adapté au contexte."],"example":{"q":"Pourquoi « télégraphe » aide-t-il à comprendre « téléphone » ?","s":["Le préfixe grec télé- renvoie à l’idée de distance.","On reconnaît un élément commun de formation.","L’étymologie aide à construire un réseau de mots."]},"trap":"Croire qu’un mot familier est toujours « faux » : il peut être correct mais inadapté au contexte.","retain":["Formation des mots = clé du sens.","Étymologie aide sans remplacer le contexte.","Registre = choix selon situation."],"quiz":[]},{"level":"5","id":"fr5j","name":"Phrase simple, complexe et non verbale","icon":"🧩","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Phrase simple, complexe et non verbale ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une phrase peut être verbale ou non verbale.","La phrase complexe contient plusieurs propositions.","La ponctuation et les relations entre propositions assurent cohérence et progression."],"method":["Repère les verbes conjugués.","Délimite les propositions.","Observe comment elles s’enchaînent."],"example":{"q":"« Quelle nuit étrange ! Le vent souffle et la pluie frappe les vitres. »","s":["« Quelle nuit étrange ! » est une phrase non verbale.","La seconde phrase contient deux propositions.","Elles sont coordonnées par « et »."]},"trap":"Définir une phrase uniquement comme « sujet + verbe + complément ».","retain":["Une phrase peut être non verbale.","Plusieurs verbes conjugués signalent souvent plusieurs propositions.","La ponctuation construit le sens."],"quiz":[]},{"level":"5","id":"fr5k","name":"Sujet, groupe verbal et compléments","icon":"🎯","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Sujet, groupe verbal et compléments ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["On analyse la phrase en groupes fonctionnels : sujet, groupe verbal, groupes circonstanciels.","COD, COI et attribut du sujet appartiennent à des constructions différentes du verbe.","Les manipulations syntaxiques permettent de justifier l’analyse."],"method":["Repère le verbe.","Cherche son sujet et ses compléments essentiels.","Teste déplacement/suppression pour les groupes circonstanciels."],"example":{"q":"Analyse « Dans la cour, les élèves trouvent le spectacle amusant. »","s":["« Dans la cour » : complément circonstanciel de lieu.","« les élèves » : sujet.","« le spectacle » : COD de « trouvent ».","« amusant » : attribut du COD dans cette construction, notion avancée ; retiens surtout le lien avec « spectacle »."]},"trap":"Appliquer une étiquette sans faire de test syntaxique.","retain":["Manipuler pour vérifier.","Le verbe organise une grande partie de la phrase.","Le sens et la syntaxe se contrôlent ensemble."],"quiz":[]},{"level":"5","id":"fr5l","name":"Classes de mots : déterminants, pronoms, adverbes, prépositions","icon":"🏷️","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Classes de mots : déterminants, pronoms, adverbes, prépositions ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les déterminants accompagnent un nom ; les pronoms remplacent ou désignent.","Les prépositions introduisent un groupe ; les adverbes sont généralement invariables.","Les mots subordonnants introduisent certaines propositions dépendantes."],"method":["Observe le mot dans sa phrase.","Teste s’il accompagne un nom ou le remplace.","Repère les mots invariables qui introduisent ou précisent."],"example":{"q":"Dans « Cette fille parle doucement à son frère », identifie « cette », « doucement », « à ».","s":["« cette » : déterminant démonstratif.","« doucement » : adverbe.","« à » : préposition."]},"trap":"Identifier la classe d’un mot sans regarder son emploi dans la phrase.","retain":["Classe grammaticale dépend de propriétés et de l’emploi.","Déterminant ≠ pronom.","Adverbes et prépositions sont invariables."],"quiz":[]},{"level":"5","id":"fr5m","name":"Le groupe nominal étendu","icon":"🌿","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Le groupe nominal étendu ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le groupe nominal étendu ajoute des expansions autour du nom noyau.","Adjectif, complément du nom et proposition relative peuvent préciser le nom.","Ces expansions ont des effets de précision, de description ou de caractérisation."],"method":["Repère le nom noyau.","Supprime les expansions pour trouver le groupe minimal.","Nomme chaque expansion et explique ce qu’elle ajoute."],"example":{"q":"Dans « la vieille maison qui domine la vallée », quelle expansion est « qui domine la vallée » ?","s":["Elle complète « maison ».","Elle contient un verbe conjugué et commence par « qui ».","C’est une proposition subordonnée relative."]},"trap":"Confondre complément du nom et complément du verbe.","retain":["Le nom noyau commande le GN.","Les expansions enrichissent le nom.","La relative est une expansion du nom."],"quiz":[]},{"level":"5","id":"fr5n","name":"Juxtaposer et coordonner pour construire un texte","icon":"🔗","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Juxtaposer et coordonner pour construire un texte ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Juxtaposition et coordination relient des propositions de même niveau syntaxique.","Le choix du coordonnant précise le rapport logique : opposition, cause, conséquence, addition…","La variété des liaisons améliore la cohérence d’un texte."],"method":["Repère le rapport de sens.","Choisis le connecteur qui correspond.","Relis pour vérifier que le lien est logique."],"example":{"q":"Complète : « Il voulait partir, ___ la route était fermée. »","s":["Le rapport est une opposition à son projet.","« mais » convient.","« car » changerait le rapport : il introduirait une cause."]},"trap":"Choisir un connecteur seulement pour éviter une répétition, sans vérifier le sens.","retain":["Connecteurs = relations logiques.","Coordination relie des éléments de même niveau.","Le sens guide le choix."],"quiz":[]},{"level":"5","id":"fr5o","name":"Discours direct et discours indirect","icon":"💬","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Discours direct et discours indirect ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le discours direct reproduit les paroles avec une mise en forme spécifique.","Le discours indirect intègre les paroles dans la phrase du narrateur.","Le passage de l’un à l’autre peut modifier pronoms, repères de temps et ponctuation."],"method":["Repère qui parle.","Choisis direct ou indirect.","Adapte pronoms et temps sans changer le sens."],"example":{"q":"Transforme : Léa dit : « Je viendrai demain. »","s":["Verbe introducteur : « dit ».","On remplace « je » par « elle ».","Selon le contexte : « Léa dit qu’elle viendra demain. »"]},"trap":"Garder les guillemets et les deux-points dans un discours indirect.","retain":["Direct = paroles montrées.","Indirect = paroles intégrées.","Pronoms et repères doivent rester cohérents."],"quiz":[]},{"level":"5","id":"fr5p","name":"Présent, imparfait, futur : formes et emplois","icon":"⏳","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Présent, imparfait, futur : formes et emplois ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Identifier un temps suppose d’observer radical et terminaison.","Le présent a plusieurs emplois : actuel, habitude, vérité générale, narration.","Imparfait et futur ont eux aussi des valeurs liées au contexte."],"method":["Identifie la forme.","Repère les indices temporels.","Explique la valeur dans la phrase, pas seulement le nom du temps."],"example":{"q":"« Chaque hiver, la rivière débordait. » Quelle valeur de l’imparfait ?","s":["L’expression « chaque hiver » indique une répétition.","L’imparfait a ici une valeur d’habitude dans le passé."]},"trap":"Donner la même valeur à tous les verbes d’un même temps.","retain":["Forme du temps ≠ valeur unique.","Le contexte indique l’emploi.","Justifier par un indice."],"quiz":[]},{"level":"5","id":"fr5q","name":"Passé simple, passé composé et plus-que-parfait","icon":"🕰️","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Passé simple, passé composé et plus-que-parfait ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le passé simple est fréquent dans le récit écrit ; le passé composé dans de nombreux discours et récits proches de l’oral.","Le plus-que-parfait exprime souvent un fait antérieur à un autre fait passé.","Les temps composés associent auxiliaire et participe passé."],"method":["Situe les événements sur une ligne du temps.","Choisis le temps en fonction de leur relation.","Vérifie la forme de l’auxiliaire et du participe."],"example":{"q":"« Il comprit qu’il avait oublié ses clés. » Pourquoi plus-que-parfait ?","s":["L’oubli se produit avant le moment où il comprend.","« avait oublié » marque l’antériorité dans le passé."]},"trap":"Utiliser le plus-que-parfait pour n’importe quel événement passé.","retain":["Plus-que-parfait = antériorité passée fréquente.","Passé simple = récit écrit de premier plan.","Temps composés = auxiliaire + participe."],"quiz":[]},{"level":"5","id":"fr5r","name":"Conditionnel et impératif","icon":"🎚️","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Conditionnel et impératif ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le conditionnel présent associe généralement le radical du futur aux terminaisons de l’imparfait.","Il exprime notamment hypothèse, souhait, information non confirmée ou politesse selon le contexte.","L’impératif sert à agir sur le destinataire."],"method":["Repère l’intention.","Construis correctement la forme verbale.","Explique la valeur produite."],"example":{"q":"« Pourrais-tu m’aider ? » Quelle valeur du conditionnel ?","s":["La question est une demande.","Le conditionnel atténue et rend la demande plus polie."]},"trap":"Croire que le conditionnel exprime seulement une condition.","retain":["Conditionnel = plusieurs valeurs.","Radical du futur + terminaisons de l’imparfait au présent.","Le contexte décide de l’effet."],"quiz":[]},{"level":"5","id":"fr5s","name":"Accords dans le groupe nominal et avec l’attribut","icon":"✅","domain":"Orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Accords dans le groupe nominal et avec l’attribut ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les accords du groupe nominal se raisonnent à partir du nom noyau.","L’attribut du sujet s’accorde avec le sujet quand il est adjectival.","Les groupes longs exigent de repérer le donneur d’accord plutôt que le mot voisin."],"method":["Repère le donneur d’accord.","Détermine genre et nombre.","Contrôle chaque receveur d’accord."],"example":{"q":"Complète : « Les maisons du village semblent ancien… »","s":["Sujet : « les maisons », féminin pluriel.","« du village » ne change pas le donneur d’accord.","Attribut : « anciennes »."]},"trap":"Accorder avec le nom le plus proche.","retain":["Donneur d’accord d’abord.","Le groupe intercalé ne commande pas forcément l’accord.","Justifier l’accord est plus sûr que deviner."],"quiz":[]},{"level":"5","id":"fr5t","name":"Accord sujet-verbe : cas complexes","icon":"🤝","domain":"Orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Accord sujet-verbe : cas complexes ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le sujet peut être séparé du verbe par des compléments.","Un sujet peut comporter plusieurs noms.","L’accord se fait avec le sujet réel, non avec le mot immédiatement placé avant le verbe."],"method":["Encadre le verbe.","Remplace tout le sujet par un pronom.","Choisis la terminaison correspondante."],"example":{"q":"Choisis : « Le bruit des vagues couvre / couvrent nos voix. »","s":["Sujet noyau : « bruit ».","Remplacement : « il couvre ».","Réponse : « couvre »."]},"trap":"Accorder avec « vagues » parce que ce mot est juste avant le verbe.","retain":["Repérer le noyau du sujet.","Remplacement pronominal efficace.","Plusieurs noms coordonnés peuvent former un sujet pluriel."],"quiz":[]},{"level":"5","id":"fr5u","name":"Accord du participe passé avec être et avoir","icon":"🧷","domain":"Orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Accord du participe passé avec être et avoir ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Avec être, le participe passé s’accorde généralement avec le sujet.","Avec avoir, il ne s’accorde pas avec le sujet ; dans le programme, on raisonne notamment sur un COD placé avant.","Il faut distinguer COD et COI avant de décider."],"method":["Repère l’auxiliaire.","Cherche le sujet et, avec avoir, le COD.","Observe la position du COD puis applique la règle étudiée."],"example":{"q":"Complète : « Les chansons que j’ai écouté… »","s":["Auxiliaire avoir.","COD = « que », qui reprend « les chansons », placé avant.","On écrit « écoutées »."]},"trap":"Accorder systématiquement avec le sujet, même avec avoir.","retain":["Être → accord avec sujet dans les cas étudiés.","Avoir → chercher le COD.","Analyse avant orthographe."],"quiz":[]},{"level":"5","id":"fr5v","name":"Orthographe lexicale, homophones et dictée","icon":"✍️","domain":"Vocabulaire et orthographe lexicale","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Orthographe lexicale, homophones et dictée ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["L’orthographe lexicale s’appuie sur morphologie, étymologie, familles et mémorisation.","Les homophones se distinguent par leur classe grammaticale et leur sens.","Une dictée efficace entraîne le raisonnement et la relecture ciblée."],"method":["Repère les zones de doute.","Explique chaque choix avec une règle ou une famille.","Relis par catégories : verbes, accords, homophones, mots lexicaux."],"example":{"q":"Comment choisir entre « a » et « à » ?","s":["« a » est une forme du verbe avoir et peut devenir « avait ».","« à » est une préposition et ne se conjugue pas.","Le test de remplacement permet de décider."]},"trap":"Apprendre des listes d’homophones sans utiliser de tests syntaxiques.","retain":["Classe grammaticale avant le son.","Relecture ciblée par familles d’erreurs.","Justifier permet d’automatiser."],"quiz":[]},{"level":"5","id":"fr5w","name":"Raconter, décrire et faire évoluer un texte","icon":"📝","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Raconter, décrire et faire évoluer un texte ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Un texte long se construit par étapes : plan, premier jet, révision, correction.","La cohérence dépend des temps, connecteurs, reprises et paragraphes.","En 5e, on développe progressivement des écrits plus longs et structurés."],"method":["Définis situation et intention.","Organise 3 ou 4 étapes.","Révise contenu puis langue."],"example":{"q":"Écris le début d’une aventure où un objet banal devient dangereux.","s":["Présente l’objet dans une situation normale.","Fais apparaître un premier indice inquiétant.","Montre la réaction du personnage.","Termine le paragraphe par une tension qui donne envie de lire la suite."]},"trap":"Corriger seulement l’orthographe sans améliorer l’organisation.","retain":["Révision = sens puis langue.","Paragraphes = étapes du raisonnement ou du récit.","Un brouillon est fait pour changer."],"quiz":[]},{"level":"5","id":"fr5x","name":"Justifier, analyser et construire un paragraphe","icon":"🧱","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Justifier, analyser et construire un paragraphe ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Un paragraphe analytique associe idée, preuve et explication.","Les connecteurs rendent visibles les relations logiques.","La citation doit être courte, intégrée et commentée."],"method":["Énonce l’idée.","Choisis une preuve précise.","Explique comment cette preuve soutient l’idée."],"example":{"q":"Montre qu’un personnage est courageux.","s":["Idée : il agit malgré le danger.","Preuve : citer un geste ou une parole précise.","Explication : montrer en quoi ce geste suppose un risque.","Conclusion locale : cela construit son héroïsme."]},"trap":"Enchaîner plusieurs citations sans commentaire.","retain":["Idée → preuve → explication.","Citation courte et intégrée.","Connecteurs logiques utiles."],"quiz":[]},{"level":"5","id":"fr5y","name":"Brouillon, révision et outils de langue","icon":"🛠️","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Brouillon, révision et outils de langue ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le brouillon n’est pas une copie sale : c’est un espace de recherche.","Réviser signifie déplacer, supprimer, ajouter, préciser et reformuler.","Dictionnaire, grammaire et correcteur numérique sont des aides, pas des décideurs."],"method":["Relis d’abord l’organisation.","Ensuite la précision du vocabulaire et des phrases.","Enfin accords, conjugaison, ponctuation et orthographe."],"example":{"q":"Un correcteur souligne « leur » dans une phrase : que faire ?","s":["Ne pas accepter automatiquement.","Identifier la classe grammaticale et le sens.","Tester la correction proposée.","Valider seulement si elle correspond à la phrase."]},"trap":"Confondre correction automatique et preuve grammaticale.","retain":["Brouillon = transformation.","Relecture en plusieurs passes.","Les outils suggèrent ; l’élève raisonne."],"quiz":[]},{"level":"5","id":"fr5z","name":"Lire une œuvre et construire sa culture","icon":"📚","domain":"Lecture et culture littéraire","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Lire une œuvre et construire sa culture ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le programme construit une culture par œuvres intégrales, lectures cursives et groupements de textes.","On situe progressivement les œuvres dans leur contexte et on les met en relation.","Un carnet de lecteur conserve réactions, citations courtes, liens et questions."],"method":["Note ce qui t’étonne ou te touche.","Choisis 2 ou 3 passages clés.","Relie l’œuvre à une autre lecture, une image, une époque ou une question."],"example":{"q":"Que mettre dans une fiche de lecture utile ?","s":["Quelques repères sur l’œuvre.","Un résumé très bref sans tout raconter.","Deux éléments précis qui expliquent ton avis.","Un lien avec une autre œuvre ou une question du programme."]},"trap":"Transformer la fiche de lecture en long résumé chapitre par chapitre.","retain":["Lire = comprendre + interpréter + mémoriser.","Culture = créer des liens.","Le carnet de lecteur garde une trace personnelle."],"quiz":[]},{"level":"4","id":"fr4a","name":"Dire l’amour","icon":"❤️","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Dire l’amour ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["En 4e, le questionnement « Dire l’amour » explore les formes de l’expression amoureuse.","Poésie, lettres, récits et théâtre montrent différentes conceptions de l’amour.","Le langage amoureux utilise images, intensité, non-dits et variations de registre."],"method":["Identifie la situation d’énonciation.","Repère les images et le registre.","Explique la vision de l’amour construite par le texte."],"example":{"q":"Pourquoi une métaphore peut-elle être importante dans un poème amoureux ?","s":["Elle donne une forme sensible à un sentiment abstrait.","Elle peut idéaliser, dramatiser ou nuancer l’émotion.","Son effet dépend du contexte."]},"trap":"Réduire tous les textes amoureux à la même vision du sentiment.","retain":["L’expression amoureuse varie selon genres et époques.","Images et voix construisent le sentiment.","Contexte et destinataire comptent."],"quiz":[]},{"level":"4","id":"fr4b","name":"Individu et société : confrontations de valeurs","icon":"⚖️","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Individu et société : confrontations de valeurs ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le programme interroge les conflits entre choix individuels et valeurs collectives.","Le théâtre et le récit mettent en scène dilemmes, révoltes, obéissance et transgression.","Analyser un conflit suppose d’identifier les valeurs défendues par chaque camp."],"method":["Nommer les valeurs en conflit.","Repérer les arguments et les conséquences.","Éviter de juger avant d’avoir compris les positions."],"example":{"q":"Un personnage refuse une loi qu’il juge injuste. Quelle question faut-il poser ?","s":["Quelle valeur défend-il ?","Quelle valeur la société ou l’autorité oppose-t-elle ?","Quels risques prend-il ?","Le texte nous invite-t-il à trancher ou à hésiter ?"]},"trap":"Résumer le conflit à « gentil contre méchant ».","retain":["Un dilemme confronte des valeurs.","Comprendre les deux positions avant de juger.","Le théâtre rend le conflit visible et audible."],"quiz":[]},{"level":"4","id":"fr4c","name":"La fiction pour interroger le réel","icon":"🪞","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « La fiction pour interroger le réel ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Réalisme et naturalisme cherchent notamment à représenter la société du XIXe siècle.","Le fantastique introduit une hésitation entre explication rationnelle et surnaturelle.","La fiction peut donc observer, déformer ou questionner le réel."],"method":["Repère les détails réalistes.","Observe le point de vue et les effets d’étrangeté.","Explique ce que la fiction fait comprendre du réel."],"example":{"q":"Un récit décrit précisément une pension puis fait entendre un bruit impossible à expliquer. Quel basculement se produit ?","s":["Le cadre réaliste rend l’événement étrange plus crédible.","Le lecteur hésite entre une cause rationnelle et surnaturelle.","C’est un mécanisme fréquent du fantastique."]},"trap":"Confondre fantastique et merveilleux : dans le fantastique, l’hésitation est essentielle.","retain":["Réalisme = représentation construite du réel.","Fantastique = hésitation.","La fiction permet de questionner la société et nos perceptions."],"quiz":[]},{"level":"4","id":"fr4d","name":"Informer, s’informer, déformer ?","icon":"📰","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Informer, s’informer, déformer ? ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une information doit être interrogée par sa source, son contexte, sa date et ses preuves.","Le titre, l’image, le cadrage et le montage influencent la réception.","Informer peut devenir déformer par erreur, sélection, exagération ou manipulation."],"method":["Identifie source et auteur.","Sépare fait, commentaire et opinion.","Croise avec au moins une autre source fiable."],"example":{"q":"Deux sites donnent des titres opposés sur le même événement. Que faire ?","s":["Lire au-delà du titre.","Comparer les faits rapportés et leurs sources.","Chercher une source indépendante ou primaire.","Repérer les mots émotionnels."]},"trap":"Partager une information parce que son titre confirme ce qu’on pense déjà.","retain":["Source + preuve + croisement.","Titre n’est pas l’article.","Image et cadrage peuvent orienter."],"quiz":[]},{"level":"4","id":"fr4e","name":"La ville, lieu de tous les possibles ?","icon":"🏙️","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « La ville, lieu de tous les possibles ? ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le questionnement complémentaire sur la ville permet d’étudier fascination, modernité, inégalités, foule et solitude.","La ville est un espace réel mais aussi un personnage ou un symbole littéraire.","Les transformations urbaines peuvent être étudiées par textes, images et films."],"method":["Repère les lieux et déplacements.","Observe le regard porté sur la ville.","Relie espaces, groupes sociaux et émotions."],"example":{"q":"Pourquoi un romancier décrit-il différemment un boulevard et une ruelle ?","s":["Les lieux peuvent correspondre à des milieux sociaux ou des ambiances différentes.","Le contraste spatial peut soutenir une critique ou une intrigue."]},"trap":"Traiter la ville comme un décor neutre.","retain":["L’espace produit du sens.","La ville peut symboliser progrès, danger ou inégalités.","Description et point de vue sont liés."],"quiz":[]},{"level":"4","id":"fr4f","name":"Lire et interpréter un texte complexe","icon":"🔍","domain":"Lecture","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Lire et interpréter un texte complexe ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["En 4e, l’interprétation mobilise structure, point de vue, procédés, contexte et implicite.","On distingue ce que le texte dit, suggère et fait ressentir.","Une analyse hiérarchise les observations plutôt que d’additionner des remarques."],"method":["Formule une hypothèse de lecture.","Choisis 2 ou 3 indices majeurs.","Explique leurs effets et relie-les à l’ensemble."],"example":{"q":"Un narrateur insiste sur les regards des autres personnages. Que peut-on analyser ?","s":["Le point de vue et la pression sociale.","Le champ lexical du regard.","La manière dont le personnage se construit sous le jugement d’autrui."]},"trap":"Relever dix procédés sans construire une idée globale.","retain":["Analyse = sélectionner et relier.","Procédé + effet + interprétation.","Justification précise obligatoire."],"quiz":[]},{"level":"4","id":"fr4g","name":"Analyser une image et un média","icon":"📷","domain":"Lecture et médias","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Analyser une image et un média ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une image possède cadrage, angle, composition, lumière, légende et contexte de diffusion.","L’association texte-image peut confirmer, nuancer ou contredire.","La réception dépend aussi du support et du public visé."],"method":["Décris sans interpréter d’abord.","Repère choix de cadrage et hiérarchie visuelle.","Interprète en revenant à la source et au contexte."],"example":{"q":"Une photo de manifestation cadre seulement trois personnes isolées. Quel effet possible ?","s":["Elle peut donner une impression de faible participation.","Un autre cadrage pourrait montrer une foule.","Le cadrage sélectionne une partie du réel."]},"trap":"Croire qu’une photographie montre automatiquement toute la réalité.","retain":["Image = sélection et construction.","Toujours regarder la source et la légende.","Comparer plusieurs cadrages."],"quiz":[]},{"level":"4","id":"fr4h","name":"Écrire un récit réaliste ou fantastique","icon":"🌙","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Écrire un récit réaliste ou fantastique ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Un récit réaliste construit un effet de vraisemblance par détails, lieux, temps et comportements cohérents.","Le fantastique fait naître une hésitation sans résoudre trop vite l’étrange.","Le point de vue et les temps du récit contrôlent ce que le lecteur sait."],"method":["Installe un cadre crédible.","Fais apparaître un détail perturbant.","Retarde l’explication et montre la réaction du personnage."],"example":{"q":"Écris l’apparition d’un événement étrange dans une chambre ordinaire.","s":["Décris deux détails quotidiens précis.","Introduis un phénomène discret mais impossible à expliquer.","Fais douter le personnage de ses sens.","Ne donne pas immédiatement une réponse surnaturelle."]},"trap":"Accumuler des monstres et des effets sans créer d’hésitation.","retain":["Crédibilité du cadre.","Étrange progressif.","Point de vue limité = suspense."],"quiz":[]},{"level":"4","id":"fr4i","name":"Argumenter : thèse, arguments et exemples","icon":"🗯️","domain":"Écriture et oral","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Argumenter : thèse, arguments et exemples ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une thèse est l’idée défendue.","Un argument donne une raison ; un exemple l’illustre ou l’appuie.","Connecteurs logiques et concessions rendent le raisonnement plus précis."],"method":["Formule la thèse en une phrase.","Classe les arguments du plus simple au plus fort.","Ajoute un exemple pertinent et explique son lien."],"example":{"q":"Sujet : « Faut-il limiter les téléphones au collège ? »","s":["Choisis une position ou nuance-la.","Argument : ils peuvent perturber l’attention.","Exemple : notifications pendant le travail.","Nuance possible : certains usages pédagogiques sont utiles."]},"trap":"Présenter un exemple sans argument, ou un argument sans lien avec la thèse.","retain":["Thèse → argument → exemple → explication.","Nuancer renforce parfois une argumentation.","Connecteurs rendent la logique visible."],"quiz":[]},{"level":"4","id":"fr4j","name":"Débattre et répondre à une objection","icon":"🎙️","domain":"Oral","objectives":["Prendre la parole de façon claire, écouter, interagir et adapter son propos à la situation.","Maîtriser les notions essentielles du chapitre « Débattre et répondre à une objection ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Débattre consiste à défendre une idée tout en répondant aux arguments des autres.","Une objection se reformule fidèlement avant d’être discutée.","Ton, vocabulaire et attitude doivent rester adaptés."],"method":["Écoute sans préparer ta réponse pendant que l’autre parle.","Reformule : « Si je comprends bien… ».","Réponds par un argument, une preuve ou une nuance."],"example":{"q":"Comment répondre à « Ton exemple n’est pas représentatif » ?","s":["Reconnaître la limite si elle existe.","Apporter une donnée ou un second exemple plus solide.","Nuancer la conclusion plutôt que nier l’objection."]},"trap":"Attaquer la personne au lieu de répondre à l’idée.","retain":["Répondre à l’argument, pas à la personne.","Reformuler montre l’écoute.","Une concession peut renforcer la crédibilité."],"quiz":[]},{"level":"4","id":"fr4k","name":"Subordination et phrase complexe","icon":"🧩","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Subordination et phrase complexe ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une proposition subordonnée dépend d’une autre proposition.","La subordination permet d’exprimer cause, conséquence, but, condition, opposition, temps ou caractérisation.","Identifier le mot subordonnant aide à comprendre le lien."],"method":["Repère les verbes conjugués.","Cherche le mot subordonnant.","Délimite la subordonnée et précise son rôle."],"example":{"q":"« Je reste parce qu’il pleut. » Quel rapport ?","s":["« parce que » introduit une subordonnée.","Elle exprime la cause de « je reste »."]},"trap":"Nommer seulement « subordonnée » sans indiquer le lien de sens.","retain":["Subordination = dépendance.","Le connecteur aide à identifier le rapport logique.","Structure et sens se complètent."],"quiz":[]},{"level":"4","id":"fr4l","name":"Relatives et conjonctives","icon":"🪢","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Relatives et conjonctives ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["La relative est introduite par un pronom relatif et complète généralement un nom.","La conjonctive est introduite par une conjonction de subordination.","Leur fonction se détermine dans la phrase."],"method":["Repère l’antécédent éventuel.","Identifie le mot introducteur.","Détermine le rôle de toute la proposition."],"example":{"q":"« Le livre que tu lis me plaît. » Quel est le rôle de « que tu lis » ?","s":["« que » est un pronom relatif.","La proposition complète « livre ».","C’est une proposition subordonnée relative."]},"trap":"Confondre « que » pronom relatif et « que » conjonction.","retain":["Relative → antécédent nominal fréquent.","Conjonctive → conjonction.","Analyser la proposition entière."],"quiz":[]},{"level":"4","id":"fr4m","name":"Interrogation directe et indirecte","icon":"❓","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Interrogation directe et indirecte ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["L’interrogation directe est autonome et porte un point d’interrogation.","L’interrogation indirecte dépend d’un verbe comme demander, savoir, ignorer.","Elle ne conserve pas toujours l’ordre des mots de la question directe."],"method":["Repère le verbe introducteur.","Transforme la question sans garder mécaniquement l’inversion.","Vérifie la ponctuation."],"example":{"q":"Transforme « Où vas-tu ? » après « Je me demande… »","s":["On introduit par « où ».","On revient à l’ordre sujet-verbe.","« Je me demande où tu vas. »"]},"trap":"Écrire « Je me demande où vas-tu ? »","retain":["Indirecte = intégrée à une phrase.","Pas d’inversion automatique.","Ponctuation adaptée à la phrase principale."],"quiz":[]},{"level":"4","id":"fr4n","name":"Compléments circonstanciels et apposition","icon":"🧭","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Compléments circonstanciels et apposition ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les compléments circonstanciels précisent notamment temps, lieu, manière, cause, but, condition ou opposition.","L’apposition apporte une caractérisation détachée.","Le déplacement et la suppression aident mais ne suffisent pas toujours : le sens compte."],"method":["Repère le groupe.","Teste déplacement/suppression.","Nomme la relation sémantique produite."],"example":{"q":"« Malgré la pluie, ils continuent. » Quelle relation ?","s":["Le groupe « malgré la pluie » est détachable.","Il exprime l’opposition ou la concession."]},"trap":"Nommer tous les compléments circonstanciels « de temps » parce qu’ils sont en début de phrase.","retain":["Fonction et sens doivent être précisés.","Position libre ne suffit pas à analyser.","Apposition = caractérisation détachée."],"quiz":[]},{"level":"4","id":"fr4o","name":"Discours rapporté : direct, indirect et effets","icon":"🗨️","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Discours rapporté : direct, indirect et effets ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le discours direct donne une impression de présence et de voix.","Le discours indirect intègre les paroles au récit.","Le choix entre les deux modifie rythme, distance et point de vue."],"method":["Identifie la voix rapportée.","Observe verbe introducteur, ponctuation et temps.","Explique l’effet du choix de discours."],"example":{"q":"Pourquoi un auteur alterne-t-il discours direct et indirect ?","s":["Le direct peut dramatiser une scène.","L’indirect peut résumer ou accélérer.","L’alternance règle la distance avec les personnages."]},"trap":"Transformer mécaniquement sans ajuster pronoms et temps.","retain":["Rapporter des paroles = choix de narration.","Pronoms, temps et repères changent parfois.","Toujours préserver le sens."],"quiz":[]},{"level":"4","id":"fr4p","name":"Registres de langue et situation de communication","icon":"🎚️","domain":"Grammaire et expression","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Registres de langue et situation de communication ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Familier, courant et soutenu dépendent de la situation et du destinataire.","À l’oral scolaire, on vise un registre courant maîtrisé voire soutenu.","Changer de registre transforme lexique, syntaxe et parfois prononciation."],"method":["Identifie destinataire et objectif.","Choisis vocabulaire et syntaxe adaptés.","Relis pour supprimer les marques inappropriées."],"example":{"q":"Réécris « J’peux pas venir, j’ai un truc » pour un message au principal.","s":["On évite les contractions familières.","On précise l’information.","Exemple : « Je ne pourrai pas être présent, car j’ai un rendez-vous médical. »"]},"trap":"Croire que le registre soutenu est toujours meilleur.","retain":["Le bon registre est celui adapté à la situation.","Syntaxe et lexique varient ensemble.","Le registre familier peut être volontaire en littérature."],"quiz":[]},{"level":"4","id":"fr4q","name":"Valeurs des temps de l’indicatif","icon":"⌛","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Valeurs des temps de l’indicatif ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les temps de l’indicatif situent mais aussi organisent le récit et le discours.","Imparfait, passé simple, passé composé, présent et plus-que-parfait produisent des effets différents.","L’antériorité et le premier/arrière-plan sont essentiels dans le récit."],"method":["Situe l’action sur une ligne du temps.","Observe si elle dure, se répète ou surgit.","Explique la valeur en contexte."],"example":{"q":"« Il marchait depuis une heure quand il aperçut la maison qu’il avait cherchée. »","s":["« marchait » : durée/arrière-plan.","« aperçut » : événement de premier plan.","« avait cherchée » : action antérieure."]},"trap":"Donner seulement le nom du temps sans expliquer son emploi.","retain":["Temps = forme + valeur.","Les relations temporelles construisent le récit.","Toujours commenter en contexte."],"quiz":[]},{"level":"4","id":"fr4r","name":"Conditionnel et hypothèse","icon":"🌦️","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Conditionnel et hypothèse ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le conditionnel peut exprimer hypothèse, futur dans le passé, souhait, politesse ou information non confirmée.","Dans une hypothèse, la concordance des temps dépend de la construction.","On distingue forme verbale et valeur."],"method":["Repère le contexte.","Identifie la valeur du conditionnel.","Vérifie la cohérence avec la proposition introduite par « si »."],"example":{"q":"« Si j’avais le temps, je viendrais. »","s":["« avais » est à l’imparfait.","« viendrais » est au conditionnel présent.","L’ensemble exprime une hypothèse peu ou non réalisée au présent."]},"trap":"Écrire « si j’aurais » dans cette construction.","retain":["Après « si » hypothétique : pas de conditionnel dans la proposition en si.","Conditionnel = plusieurs valeurs.","Concordance à vérifier."],"quiz":[]},{"level":"4","id":"fr4s","name":"Subjonctif : découverte et emplois fréquents","icon":"🌫️","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Subjonctif : découverte et emplois fréquents ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le subjonctif apparaît notamment après certaines expressions de volonté, nécessité, doute ou sentiment.","Il présente souvent le fait comme envisagé, souhaité ou évalué plutôt que simplement affirmé.","Les formes de être et avoir sont très fréquentes."],"method":["Repère le déclencheur.","Identifie le sujet de la subordonnée.","Choisis la forme correcte du subjonctif."],"example":{"q":"Complète : « Il faut que tu ___ prêt. »","s":["Expression de nécessité : « il faut que ».","Subjonctif présent de être : « sois ».","« Il faut que tu sois prêt. »"]},"trap":"Mettre automatiquement le subjonctif après chaque « que ».","retain":["Le contexte et le verbe introducteur comptent.","Subjonctif = mode, pas temps chronologique.","Mémoriser les formes fréquentes."],"quiz":[]},{"level":"4","id":"fr4t","name":"Voix active et voix passive","icon":"🔄","domain":"Grammaire et expression","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Voix active et voix passive ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["À la voix active, le sujet accomplit généralement l’action.","À la voix passive, le sujet subit l’action ; l’agent peut être exprimé ou non.","Changer de voix modifie la focalisation de l’information."],"method":["Repère sujet, verbe et COD à l’actif.","Transforme le COD en sujet du passif.","Conjugue être au même temps et accorde le participe."],"example":{"q":"Transforme « Les élèves ont décoré la salle. » au passif.","s":["COD « la salle » devient sujet.","Être au passé composé : « a été ».","Participe : « décorée ».","« La salle a été décorée par les élèves. »"]},"trap":"Changer le temps du verbe pendant la transformation.","retain":["Actif/passif modifie le point de vue grammatical.","Le temps doit rester équivalent.","Participe passé accordé avec le sujet au passif."],"quiz":[]},{"level":"4","id":"fr4u","name":"Accords complexes et participe passé","icon":"✅","domain":"Orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Accords complexes et participe passé ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les accords complexes exigent de repérer les donneurs d’accord.","Avec avoir, la place et la fonction du COD peuvent intervenir.","Le raisonnement grammatical est plus fiable que l’intuition sonore."],"method":["Analyse la phrase avant d’écrire.","Repère auxiliaire, sujet et COD.","Justifie la terminaison choisie."],"example":{"q":"« Les lettres qu’elle a écrit… »","s":["COD « qu’ » reprend « les lettres » et est placé avant.","On accorde le participe passé : « écrites »."]},"trap":"Chercher l’accord uniquement à l’oreille.","retain":["Analyse avant accord.","Fonction + position du COD.","Relecture ciblée des participes."],"quiz":[]},{"level":"4","id":"fr4v","name":"Lexique, connotation et figures de style","icon":"🎨","domain":"Vocabulaire et analyse littéraire","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Lexique, connotation et figures de style ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Dénotation = sens de base ; connotation = valeurs et associations suggérées.","Métaphore, comparaison, personnification, hyperbole, antithèse ou ironie créent des effets.","Le lexique peut former des réseaux qui orientent l’interprétation."],"method":["Repère les mots d’un même champ.","Distingue sens littéral et connotations.","Explique l’effet dans le passage."],"example":{"q":"Que suggère le mot « tanière » pour parler d’un appartement ?","s":["Dénotation : abri d’un animal.","Connotations possibles : retrait, obscurité, enfermement.","Le choix du mot caractérise le lieu et peut-être son habitant."]},"trap":"Donner une connotation comme une définition universelle.","retain":["Connotation dépend du contexte.","Figure de style = outil d’interprétation.","Réseau lexical construit une atmosphère."],"quiz":[]},{"level":"4","id":"fr4w","name":"Versification et lecture poétique","icon":"🎼","domain":"Lecture et vocabulaire littéraire","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Versification et lecture poétique ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Vers, strophe, rime, rythme, enjambement et sonorités structurent de nombreux poèmes.","La forme peut soutenir ou contrarier le sens.","La poésie moderne peut s’affranchir des formes régulières."],"method":["Observe la disposition.","Lis à voix haute pour entendre le rythme.","Relie un choix formel à une émotion ou une idée."],"example":{"q":"Quel peut être l’effet d’un enjambement ?","s":["La phrase déborde la fin du vers.","Cela peut créer élan, attente ou rupture.","L’effet doit être expliqué dans le passage précis."]},"trap":"Croire qu’un poème doit forcément rimer.","retain":["Forme poétique variée.","Rythme se lit autant qu’il se compte.","Forme et sens dialoguent."],"quiz":[]},{"level":"4","id":"fr4x","name":"Orthographe, homophones et relecture ciblée","icon":"✍️","domain":"Vocabulaire et orthographe lexicale","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Orthographe, homophones et relecture ciblée ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les homophones grammaticaux se distinguent par l’analyse syntaxique.","Les radicaux verbaux et familles de mots aident à orthographier.","Une relecture efficace traite une famille d’erreurs à la fois."],"method":["Première passe : verbes et sujets.","Deuxième : accords dans les groupes nominaux.","Troisième : homophones, participes et mots lexicaux."],"example":{"q":"Comment choisir « ce » ou « se » ?","s":["« ce » est déterminant ou pronom démonstratif.","« se » est pronom personnel devant un verbe pronominal.","On analyse la structure : « ce livre » / « il se lève »."]},"trap":"Relire seulement « au feeling » de gauche à droite.","retain":["Relecture par catégories.","Homophone = analyse grammaticale.","Famille de mots aide l’orthographe lexicale."],"quiz":[]},{"level":"4","id":"fr4y","name":"Construire un paragraphe argumenté","icon":"🧱","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Construire un paragraphe argumenté ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le paragraphe argumenté commence par une idée directrice.","Il s’appuie sur preuve ou exemple puis analyse.","Les connecteurs organisent raisonnement, opposition, cause et conséquence."],"method":["Écris l’idée.","Insère une preuve ou un exemple précis.","Explique et relie à la question."],"example":{"q":"Montre qu’un article cherche à provoquer une réaction.","s":["Identifie les mots évaluatifs ou émotionnels.","Cite un élément bref.","Explique comment il oriente le lecteur.","Relie cette stratégie à l’intention de l’article."]},"trap":"Commencer par une citation sans annoncer l’idée.","retain":["Idée → preuve → analyse.","Connecteurs visibles.","Conclusion locale liée à la question."],"quiz":[]},{"level":"4","id":"fr4z","name":"Réviser, corriger et améliorer un texte","icon":"🧰","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Réviser, corriger et améliorer un texte ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Réviser implique contenu, structure, cohésion, vocabulaire et correction de la langue.","On peut comparer plusieurs versions d’un même passage.","Les outils numériques aident, mais doivent être contrôlés."],"method":["Relis le plan et les paragraphes.","Traque répétitions et phrases imprécises.","Termine par une relecture grammaticale ciblée."],"example":{"q":"Une phrase fait cinq lignes et contient quatre « et ». Que faire ?","s":["Identifier les idées distinctes.","Créer plusieurs phrases ou subordonnées selon les liens.","Choisir des connecteurs précis.","Vérifier ponctuation et pronoms de reprise."]},"trap":"Corriger l’orthographe sans toucher à une phrase incompréhensible.","retain":["Sens avant forme.","Réviser peut transformer profondément.","Outil numérique ≠ décision automatique."],"quiz":[]},{"level":"3","id":"fr3a","name":"Se raconter, se représenter","icon":"🪞","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Se raconter, se représenter ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["L’écriture de soi explore mémoire, identité, vérité et reconstruction.","Autobiographie, journal, mémoires, autoportrait et roman autobiographique proposent des pactes de lecture différents.","Se raconter suppose de sélectionner, organiser et interpréter sa propre expérience."],"method":["Identifie qui raconte, qui est raconté et à quel moment.","Observe le rapport entre mémoire et présent de l’écriture.","Questionne les choix de composition et de sincérité."],"example":{"q":"Pourquoi un récit autobiographique n’est-il pas une copie parfaite du passé ?","s":["La mémoire sélectionne et transforme.","L’auteur écrit depuis un moment postérieur.","Le récit organise les événements pour leur donner un sens."]},"trap":"Confondre « autobiographique » avec « absolument objectif ».","retain":["Écriture de soi = construction.","Auteur, narrateur et personnage peuvent être liés.","Mémoire et composition sont essentielles."],"quiz":[]},{"level":"3","id":"fr3b","name":"Dénoncer les travers de la société","icon":"🎯","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Dénoncer les travers de la société ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Satire, caricature, ironie, comédie et apologue permettent de critiquer.","Le rire et l’exagération peuvent révéler des injustices ou comportements absurdes.","Comprendre l’ironie exige de distinguer ce qui est dit et ce qui est visé."],"method":["Identifie la cible.","Repère les procédés de déformation ou de décalage.","Explique le jugement implicite porté par le texte."],"example":{"q":"Un narrateur félicite « l’excellente idée » de jeter tous les déchets dans la rivière. Est-ce forcément un éloge ?","s":["Le contexte rend l’éloge absurde.","Il peut s’agir d’ironie.","Le sens réel est critique."]},"trap":"Prendre une phrase ironique au pied de la lettre.","retain":["Satire = critique par procédés.","Ironie = décalage entre dit et visé.","Identifier cible et effet."],"quiz":[]},{"level":"3","id":"fr3c","name":"Visions poétiques du monde","icon":"🌌","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Visions poétiques du monde ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["La poésie transforme le monde par images, rythme, voix et forme.","Le poète peut célébrer, inquiéter, résister ou renouveler notre perception.","Les formes modernes et contemporaines élargissent l’idée même de poème."],"method":["Repère la voix et le mouvement du poème.","Observe les réseaux d’images et de sons.","Relie forme, émotion et vision du monde."],"example":{"q":"Pourquoi une disposition inhabituelle des mots sur la page peut-elle avoir du sens ?","s":["Elle peut imiter un mouvement ou fragmenter la lecture.","Elle crée un rythme visuel.","Elle fait partie de la signification, pas seulement de la décoration."]},"trap":"Analyser seulement les rimes.","retain":["Poésie = voix, sons, images, espace de la page.","La forme peut argumenter ou émouvoir.","Toujours expliquer l’effet."],"quiz":[]},{"level":"3","id":"fr3d","name":"Agir dans la cité : individu et pouvoir","icon":"🏛️","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Agir dans la cité : individu et pouvoir ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les œuvres interrogent obéissance, résistance, responsabilité et pouvoir.","Un personnage peut être confronté à la loi, à l’État, à un groupe ou à sa conscience.","La littérature met à l’épreuve les valeurs civiques et morales."],"method":["Repère la forme du pouvoir.","Identifie le conflit de valeurs.","Analyse choix, risques et conséquences."],"example":{"q":"Un personnage refuse un ordre légal mais injuste à ses yeux. Quelle tension apparaît ?","s":["Légalité et justice peuvent entrer en conflit.","Le personnage doit choisir entre obéissance et conscience.","Le texte peut inviter à débattre sans réponse simple."]},"trap":"Réduire le pouvoir à une seule personne : il peut aussi être social, institutionnel ou collectif.","retain":["Pouvoir = relation.","Résistance implique choix et responsabilité.","La littérature permet de penser la cité."],"quiz":[]},{"level":"3","id":"fr3e","name":"Progrès et rêves scientifiques","icon":"🚀","domain":"Culture littéraire et artistique — programme 2020 applicable","objectives":["Lire, comprendre et interpréter des œuvres et des textes en construisant une culture littéraire.","Maîtriser les notions essentielles du chapitre « Progrès et rêves scientifiques ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le questionnement complémentaire examine espoirs, peurs et responsabilités liés au progrès.","Science-fiction et anticipation projettent des possibles pour interroger le présent.","Un progrès technique peut créer à la fois bénéfices, risques et dilemmes éthiques."],"method":["Identifie l’innovation imaginée.","Cherche les conséquences voulues et imprévues.","Relie la fiction à une question contemporaine."],"example":{"q":"Une invention supprime toute maladie mais enregistre toutes les données personnelles. Quel débat ?","s":["Bénéfice sanitaire contre liberté et vie privée.","La fiction met en tension plusieurs valeurs.","Il faut argumenter plutôt que choisir automatiquement."]},"trap":"Traiter la science-fiction comme une simple prédiction du futur.","retain":["Anticipation = miroir du présent.","Progrès = avantages + risques.","Question éthique = valeurs en tension."],"quiz":[]},{"level":"3","id":"fr3f","name":"Comprendre et interpréter des textes complexes","icon":"🔎","domain":"Lecture","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Comprendre et interpréter des textes complexes ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["En 3e, on croise texte, contexte, procédés, structure et connaissances culturelles.","L’implicite, l’ironie, les points de vue et les registres demandent une lecture active.","Une interprétation solide hiérarchise les indices et envisage des nuances."],"method":["Formule la question centrale du passage.","Sélectionne les indices les plus significatifs.","Construis une interprétation organisée et nuancée."],"example":{"q":"Un texte change brusquement du « je » au « nous ». Que peut-on analyser ?","s":["Le passage de l’expérience individuelle à une portée collective.","La stratégie d’implication du lecteur ou du groupe.","Le contexte permet de préciser l’effet."]},"trap":"Commenter chaque ligne séparément sans construire de progression.","retain":["Hiérarchiser les indices.","Formuler une idée globale.","Nuancer si plusieurs lectures sont possibles."],"quiz":[]},{"level":"3","id":"fr3g","name":"Argumentation : thèse, arguments, réfutation","icon":"⚔️","domain":"Écriture et lecture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Argumentation : thèse, arguments, réfutation ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une argumentation peut défendre, contester ou nuancer une thèse.","La réfutation répond directement à un argument adverse.","La concession reconnaît une partie d’un argument avant de limiter sa portée."],"method":["Formule la thèse adverse avec loyauté.","Choisis une objection précise.","Réponds par raisonnement, exemple ou donnée pertinente."],"example":{"q":"Comment construire une concession ?","s":["Reconnaître : « Certes, cette solution est rapide… »","Limiter : « …mais elle entraîne un coût important. »","Relier à sa propre thèse."]},"trap":"Caricaturer la position adverse pour la réfuter plus facilement.","retain":["Réfuter l’argument réel.","Concession = reconnaître puis nuancer.","Exemple n’est pas preuve absolue."],"quiz":[]},{"level":"3","id":"fr3h","name":"Sources, médias et esprit critique","icon":"🧭","domain":"Lecture et médias","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Sources, médias et esprit critique ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une information fiable se juge par source, auteur, date, méthode, preuves et possibilité de vérification.","Biais de sélection, montage, chiffres isolés et images sorties du contexte peuvent tromper.","L’esprit critique ne consiste pas à tout rejeter mais à évaluer."],"method":["Remonte à la source originale.","Compare plusieurs sources indépendantes.","Vérifie chiffres, contexte et date."],"example":{"q":"Une capture d’écran cite « une étude » sans lien ni auteur. Que faire ?","s":["Chercher l’étude originale.","Vérifier qui l’a menée et sur quel échantillon.","Comparer avec d’autres sources.","Suspendre son jugement tant que les preuves manquent."]},"trap":"Croire qu’être sceptique signifie dire « tout est faux ».","retain":["Critique = méthode de vérification.","Source primaire utile.","Contexte des chiffres essentiel."],"quiz":[]},{"level":"3","id":"fr3i","name":"Écrire un récit autobiographique","icon":"✒️","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Écrire un récit autobiographique ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Écrire sur soi suppose de choisir un épisode, un point de vue et une distance.","Le récit peut alterner scène vécue et commentaire du narrateur actuel.","Les détails sensoriels rendent le souvenir concret sans tout raconter."],"method":["Choisis un moment précis.","Fais revivre la scène avec quelques détails.","Ajoute ce que tu comprends aujourd’hui de cet événement."],"example":{"q":"Raconte un souvenir où tu as changé d’avis.","s":["Commence dans une scène précise.","Montre ce que tu pensais alors.","Fais apparaître l’événement qui fait évoluer ton regard.","Termine par une réflexion du présent."]},"trap":"Raconter toute sa vie au lieu de construire un épisode significatif.","retain":["Sélection et composition.","Deux temporalités : vécu et écriture.","Détail concret + réflexion."],"quiz":[]},{"level":"3","id":"fr3j","name":"Écrire un développement argumenté","icon":"🧱","domain":"Écriture","objectives":["Écrire de façon claire, organisée et progressive, puis relire et améliorer son texte.","Maîtriser les notions essentielles du chapitre « Écrire un développement argumenté ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Un développement argumenté répond à une question par plusieurs paragraphes organisés.","Chaque paragraphe développe une idée et l’appuie par exemples ou références.","Introduction et conclusion encadrent la réflexion sans répéter mécaniquement."],"method":["Analyse le sujet et définis les mots-clés.","Construis 2 ou 3 axes.","Dans chaque paragraphe : idée, exemple, analyse, lien au sujet."],"example":{"q":"Sujet : « La littérature peut-elle faire agir ? »","s":["Définis ce que signifie « faire agir ».","Axe possible : dénoncer et faire prendre conscience.","Axe possible : susciter empathie et débat.","Nuance : une œuvre n’entraîne pas automatiquement une action."]},"trap":"Faire une liste d’exemples sans raisonnement.","retain":["Plan = progression d’idées.","Exemple doit être analysé.","Répondre précisément aux termes du sujet."],"quiz":[]},{"level":"3","id":"fr3k","name":"Méthode de compréhension type brevet","icon":"🎓","domain":"Lecture et méthodologie","objectives":["Lire avec autonomie, comprendre, interpréter et justifier ses réponses par des indices précis.","Maîtriser les notions essentielles du chapitre « Méthode de compréhension type brevet ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une question de compréhension demande une réponse précise fondée sur le document.","Il faut distinguer relever, expliquer, justifier, interpréter et comparer.","La formulation de la réponse compte autant que la localisation de l’information."],"method":["Entoure le verbe de consigne.","Repère les passages utiles.","Réponds avec une phrase complète et la preuve nécessaire."],"example":{"q":"Consigne : « Expliquez pourquoi le personnage hésite. Justifiez par deux éléments. »","s":["Il faut donner la cause de l’hésitation.","Deux indices distincts du texte sont requis.","Chaque indice doit être relié à l’explication."]},"trap":"Recopier un long passage sans répondre à la question.","retain":["Verbe de consigne d’abord.","Preuve ciblée.","Explication personnelle fondée sur le texte."],"quiz":[]},{"level":"3","id":"fr3l","name":"Grammaire et réécriture type brevet","icon":"🧪","domain":"Grammaire et méthodologie","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Grammaire et réécriture type brevet ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Une réécriture exige d’identifier précisément ce qui change : sujet, temps, genre, nombre ou personne.","Chaque changement déclenche une chaîne d’accords.","La méthode consiste à repérer tous les mots dépendants avant d’écrire."],"method":["Surligne l’élément transformé.","Liste tous les mots qui dépendent de lui.","Réécris puis contrôle chaque terminaison."],"example":{"q":"Transforme « Elle entra, surprise, puis posa son sac » avec « elles ».","s":["« elle » → « elles ».","« entra » → « entrèrent ».","« surprise » → « surprises ».","« posa » → « posèrent »."]},"trap":"Modifier seulement le pronom sans suivre la chaîne d’accords.","retain":["Réécriture = propagation des changements.","Repérer avant d’écrire.","Contrôle final mot par mot."],"quiz":[]},{"level":"3","id":"fr3m","name":"Phrase complexe et rapports logiques","icon":"🧩","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Phrase complexe et rapports logiques ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["La phrase complexe organise des rapports de cause, conséquence, but, opposition, condition, temps ou comparaison.","Coordination, juxtaposition et subordination donnent des structures différentes.","Le choix syntaxique modifie la précision et le rythme du raisonnement."],"method":["Délimite les propositions.","Identifie le lien syntaxique.","Formule le rapport logique et son effet."],"example":{"q":"« Bien qu’il soit fatigué, il continue. » Quel rapport ?","s":["« bien que » introduit une subordonnée.","Elle exprime la concession/opposition.","Le fait de continuer est présenté comme contraire à ce qu’on attendrait."]},"trap":"Nommer le connecteur sans expliquer le rapport logique.","retain":["Syntaxe + sens.","Un même rapport peut être exprimé de plusieurs façons.","Varier les structures améliore l’écriture."],"quiz":[]},{"level":"3","id":"fr3n","name":"Relatives, conjonctives et interrogatives indirectes","icon":"🪢","domain":"Grammaire et orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Relatives, conjonctives et interrogatives indirectes ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les subordonnées ont des fonctions différentes dans la phrase.","La relative complète un nom ; la conjonctive peut compléter un verbe ou exprimer une circonstance.","L’interrogative indirecte dépend d’un verbe de questionnement ou d’incertitude."],"method":["Repère le mot introducteur.","Cherche l’antécédent éventuel.","Détermine la fonction de la proposition entière."],"example":{"q":"« Je me demande si le train arrivera. »","s":["La proposition « si le train arrivera » dépend de « je me demande ».","Elle correspond à une question intégrée.","C’est une interrogative indirecte totale."]},"trap":"Croire que toute proposition introduite par « si » exprime une condition.","retain":["Fonction de la proposition entière.","« si » peut introduire condition ou interrogation indirecte.","Contexte du verbe principal décisif."],"quiz":[]},{"level":"3","id":"fr3o","name":"Voix active, passive et tournures impersonnelles","icon":"🔄","domain":"Grammaire et expression","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Voix active, passive et tournures impersonnelles ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["La voix passive modifie la mise en avant de l’agent et du patient.","Les tournures impersonnelles utilisent souvent « il » sans référent précis : « il faut », « il semble ».","Ces structures servent à organiser l’information et le point de vue."],"method":["Repère ce qui est mis en position de sujet.","Transforme pour comparer les effets.","Explique pourquoi l’auteur choisit une structure."],"example":{"q":"Pourquoi écrire « Trois personnes ont été arrêtées » sans complément d’agent ?","s":["L’accent est mis sur les personnes arrêtées.","L’agent peut être inconnu, évident ou volontairement effacé."]},"trap":"Croire que la transformation passive est seulement un exercice mécanique.","retain":["Grammaire organise l’information.","Passif peut effacer l’agent.","Tournure impersonnelle ne renvoie pas toujours à une personne."],"quiz":[]},{"level":"3","id":"fr3p","name":"Discours direct, indirect et indirect libre","icon":"🎬","domain":"Grammaire et narration","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Discours direct, indirect et indirect libre ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le discours indirect libre mêle souvent voix du narrateur et pensée ou parole du personnage sans verbe introducteur explicite.","Il peut rapprocher le lecteur du point de vue du personnage.","Comparer les trois formes permet d’analyser la distance narrative."],"method":["Repère indices de voix et de personne.","Observe ponctuation et verbes introducteurs.","Demande qui porte l’évaluation ou l’émotion."],"example":{"q":"« Il regarda la porte. Partir maintenant ? Impossible. » Quelle voix entend-on ?","s":["Le narrateur raconte « Il regarda ».","Les phrases suivantes font entendre la pensée du personnage sans guillemets ni « pensa-t-il ».","C’est proche du discours indirect libre."]},"trap":"Chercher obligatoirement des guillemets pour repérer la voix d’un personnage.","retain":["Paroles rapportées = plusieurs dispositifs.","Indirect libre brouille les voix.","Effet = proximité avec conscience du personnage."],"quiz":[]},{"level":"3","id":"fr3q","name":"Valeurs des temps et concordance","icon":"⌛","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Valeurs des temps et concordance ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les temps organisent chronologie, point de vue et relation entre actions.","La concordance des temps assure la cohérence entre proposition principale et subordonnée.","Le conditionnel peut marquer le futur dans le passé."],"method":["Situe le repère principal.","Place les autres actions avant, pendant ou après.","Choisis le temps qui exprime cette relation."],"example":{"q":"« Il annonça qu’il partirait le lendemain. » Pourquoi conditionnel ?","s":["Le départ est futur par rapport au moment passé « annonça ».","Le conditionnel exprime ici le futur dans le passé."]},"trap":"Interpréter tout conditionnel comme une hypothèse.","retain":["Conditionnel = valeur selon contexte.","Antériorité/simultanéité/postériorité organisent les temps.","Repère temporel de référence indispensable."],"quiz":[]},{"level":"3","id":"fr3r","name":"Subjonctif : valeurs et emplois","icon":"🌫️","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Subjonctif : valeurs et emplois ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le subjonctif peut exprimer volonté, souhait, doute, émotion, nécessité ou jugement.","Il apparaît dans de nombreuses subordonnées introduites par « que ».","Il faut distinguer mode et temps : le subjonctif présent peut concerner présent ou futur selon le contexte."],"method":["Repère le déclencheur sémantique.","Identifie le sujet de la subordonnée.","Conjugue puis explique la valeur."],"example":{"q":"« Je doute qu’il vienne. » Pourquoi le subjonctif ?","s":["Le verbe « douter » présente le fait comme incertain.","« vienne » est au subjonctif présent."]},"trap":"Penser que le subjonctif « parle toujours du futur ».","retain":["Subjonctif = mode de représentation du fait.","Valeur liée au verbe ou à la construction.","Formes fréquentes à maîtriser."],"quiz":[]},{"level":"3","id":"fr3s","name":"Conditionnel : hypothèse, futur du passé, information non confirmée","icon":"☁️","domain":"Conjugaison et valeurs des temps","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Conditionnel : hypothèse, futur du passé, information non confirmée ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Le conditionnel a plusieurs valeurs distinctes.","En presse, il peut signaler une information non confirmée.","Dans le récit, il peut exprimer un événement futur par rapport à un repère passé."],"method":["Repère le genre du texte.","Cherche le repère temporel ou la source d’information.","Nomme la valeur précise."],"example":{"q":"« Le suspect serait à l’étranger. » dans un article : quelle valeur ?","s":["Le journaliste ne présente pas l’information comme certaine.","Le conditionnel marque une réserve ou information non confirmée."]},"trap":"Appeler tout conditionnel « condition ».","retain":["Valeur = contexte.","Presse : réserve possible.","Récit : futur dans le passé possible."],"quiz":[]},{"level":"3","id":"fr3t","name":"Accords du participe passé et verbes pronominaux","icon":"🧷","domain":"Orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Accords du participe passé et verbes pronominaux ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les accords du participe passé se raisonnent par auxiliaire, fonction et position.","Avec les verbes pronominaux, l’analyse du pronom et du complément peut être nécessaire.","On privilégie une démarche de raisonnement plutôt qu’une liste de recettes."],"method":["Identifie auxiliaire et construction.","Cherche le rôle du pronom ou du COD.","Justifie l’accord avant d’écrire."],"example":{"q":"Pourquoi « Elles se sont lavé les mains » n’accorde-t-il pas « lavé » avec « elles » ?","s":["Dans cette construction, « les mains » est COD placé après.","Le pronom « se » correspond à un complément indirect dans l’analyse scolaire de ce cas.","Le participe reste invariable : « lavé »."]},"trap":"Appliquer « auxiliaire être = accord avec sujet » à tous les verbes pronominaux.","retain":["Verbes pronominaux : analyser la construction.","Fonction et position comptent.","Justification avant terminaison."],"quiz":[]},{"level":"3","id":"fr3u","name":"Accord sujet-verbe et groupes complexes","icon":"🤝","domain":"Orthographe grammaticale","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Accord sujet-verbe et groupes complexes ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les sujets complexes peuvent contenir plusieurs personnes, noms coordonnés ou pronoms relatifs.","Le verbe s’accorde avec le véritable sujet grammatical.","Les écrans entre sujet et verbe augmentent le risque d’erreur."],"method":["Réduis le groupe sujet à son noyau ou pronom.","Repère les coordinations.","Avec « qui », cherche l’antécédent qui commande l’accord."],"example":{"q":"Complète : « C’est moi qui ___ responsable. » (être)","s":["« qui » reprend « moi ».","L’accord suit la personne de l’antécédent.","On écrit « suis »."]},"trap":"Accorder automatiquement le verbe après « qui » à la troisième personne.","retain":["« qui » sujet reprend un antécédent.","Identifier la personne grammaticale.","Éloignement n’annule pas l’accord."],"quiz":[]},{"level":"3","id":"fr3v","name":"Connecteurs, lexique argumentatif et nuances","icon":"🧭","domain":"Vocabulaire et expression","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Connecteurs, lexique argumentatif et nuances ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les connecteurs organisent addition, opposition, cause, conséquence, concession et conclusion.","Un lexique précis permet de nuancer degré de certitude, jugement et position.","Les mots ont des connotations qui influencent l’argumentation."],"method":["Classe les connecteurs par relation logique.","Choisis des verbes précis pour présenter une opinion.","Remplace les mots vagues par un terme adapté."],"example":{"q":"Différence entre « affirme », « suggère » et « prétend » ?","s":["« affirme » présente une prise de position nette.","« suggère » est plus indirect.","« prétend » peut introduire une distance critique selon le contexte."]},"trap":"Utiliser « donc » partout pour relier n’importe quelles idées.","retain":["Connecteur = relation précise.","Verbes de parole nuancent.","Connotation influence le jugement."],"quiz":[]},{"level":"3","id":"fr3w","name":"Figures de style et analyse stylistique","icon":"🎨","domain":"Vocabulaire et analyse littéraire","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Figures de style et analyse stylistique ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["Les figures ne sont pas des décorations : elles organisent sens, émotion et argumentation.","Métaphore, comparaison, personnification, antithèse, hyperbole, anaphore, gradation et ironie sont fréquentes.","L’analyse stylistique part d’un effet observé et revient au procédé."],"method":["Décris d’abord l’effet ressenti ou l’insistance.","Repère le procédé qui le produit.","Relie-le à l’idée du passage."],"example":{"q":"« Je marche, je tombe, je me relève, je cours. » Quel effet possible ?","s":["La succession peut créer une progression.","Si l’intensité augmente, on peut parler de gradation.","Le rythme accompagne l’évolution de l’action."]},"trap":"Lister les figures sans expliquer leur effet.","retain":["Procédé → effet → sens.","Contexte indispensable.","Stylistique = choix d’écriture."],"quiz":[]},{"level":"3","id":"fr3x","name":"Connotation, précision et formation des mots","icon":"🧬","domain":"Vocabulaire et orthographe lexicale","objectives":["Enrichir, structurer et réemployer le vocabulaire avec précision.","Maîtriser les notions essentielles du chapitre « Connotation, précision et formation des mots ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["La connotation ajoute des valeurs culturelles, affectives ou évaluatives au sens de base.","La morphologie et l’étymologie permettent de chercher le sens de manière autonome.","La précision lexicale évite les mots passe-partout."],"method":["Repère le mot vague.","Cherche un mot plus précis dans le même champ.","Vérifie registre et connotation."],"example":{"q":"Remplace « faire un discours » par un verbe plus précis selon le contexte.","s":["« prononcer un discours » est plus précis.","Dans un autre contexte, on pourrait « improviser », « préparer » ou « lire » un discours.","Le choix dépend du sens exact."]},"trap":"Remplacer un mot par un synonyme sans vérifier la nuance.","retain":["Synonymes rarement parfaitement interchangeables.","Connotation + registre.","Morphologie aide à comprendre et orthographier."],"quiz":[]},{"level":"3","id":"fr3y","name":"Oral : exposer, débattre et présenter une œuvre","icon":"🎤","domain":"Oral","objectives":["Prendre la parole de façon claire, écouter, interagir et adapter son propos à la situation.","Maîtriser les notions essentielles du chapitre « Oral : exposer, débattre et présenter une œuvre ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["En 3e, l’oral demande autonomie, structuration et prise en compte de l’auditoire.","Un exposé combine informations, sélection et explication.","Un débat exige écoute, reformulation, argumentation et gestion du temps."],"method":["Prépare une accroche et un plan clair.","Appuie-toi sur peu de notes lisibles.","Anticipe une question et prépare une réponse argumentée."],"example":{"q":"Présente une œuvre en deux minutes.","s":["Situe brièvement l’œuvre et son auteur/autrice.","Explique un enjeu essentiel.","Analyse un élément précis.","Termine par ce que l’œuvre permet de comprendre ou questionner."]},"trap":"Réciter un texte appris sans adapter sa parole à l’auditoire.","retain":["Oral = communiquer, pas réciter.","Plan visible.","Exemple précis et réponse aux questions."],"quiz":[]},{"level":"3","id":"fr3z","name":"Orthographe, dictée et révision finale","icon":"✅","domain":"Orthographe et méthodologie","objectives":["Comprendre le fonctionnement de la langue pour mieux lire, écrire et s’exprimer.","Maîtriser les notions essentielles du chapitre « Orthographe, dictée et révision finale ».","Réinvestir ces connaissances dans une phrase, un texte ou une réponse argumentée."],"keys":["La maîtrise orthographique mobilise accords, conjugaison, homophones, lexique et ponctuation.","La dictée permet d’identifier les raisonnements qui ne sont pas encore automatisés.","Une relecture efficace suit une procédure stable."],"method":["Repère les verbes et leurs sujets.","Contrôle groupes nominaux et participes passés.","Vérifie homophones, ponctuation et mots lexicaux."],"example":{"q":"Tu disposes de trois minutes de relecture : quel ordre ?","s":["1. Verbes/sujets et temps.","2. Accords des groupes nominaux et participes.","3. Homophones, ponctuation, mots signalés mentalement.","Cette méthode évite une relecture superficielle."]},"trap":"Relire tout le texte sans objectif précis.","retain":["Relecture ciblée par catégories.","Justifier les accords.","Transformer les erreurs récurrentes en liste personnelle."],"quiz":[]}];
